CREATE FUNCTION public.document_learn_date_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE before_date text;after_date text;party text;workflow_key text;pattern jsonb;prior uuid;BEGIN
IF auth.uid() IS NULL THEN RETURN NEW;END IF;
IF TG_TABLE_NAME='sales_records' THEN before_date:=OLD.date;after_date:=NEW.date;party:=NEW.venue;workflow_key:='sales_receipt_extract';ELSE before_date:=OLD.invoice_date::text;after_date:=NEW.invoice_date::text;party:=NEW.supplier_id::text;workflow_key:='invoice_extract';END IF;
IF before_date IS NOT DISTINCT FROM after_date THEN RETURN NEW;END IF;
pattern:=jsonb_build_object('kind','date','party',party,'read_year',left(before_date,4),'saved_year',left(after_date,4));
SELECT id INTO prior FROM public.ai_learned_rules WHERE tenant_id=NEW.tenant_id AND workflow=workflow_key AND name=party AND input_pattern->>'kind'='date' AND input_pattern->>'read_year'=left(before_date,4) AND output_action->>'year' IS DISTINCT FROM left(after_date,4) AND status='active' LIMIT 1;
INSERT INTO public.ai_learned_rules(tenant_id,domain,workflow,rule_type,name,input_pattern,output_action,hit_count,created_by,status) VALUES(NEW.tenant_id,CASE WHEN TG_TABLE_NAME='sales_records' THEN 'revenue' ELSE 'procurement' END,workflow_key,'date_correction',party,pattern,jsonb_build_object('year',left(after_date,4),'before',before_date,'after',after_date,'trust','human_saved_unverified','usage','reread_original_not_substitution'),1,auth.uid(),CASE WHEN prior IS NOT NULL THEN 'needs_review' ELSE 'active' END);
RETURN NEW;END $$;
CREATE TRIGGER document_learn_sales_date AFTER UPDATE OF date ON public.sales_records FOR EACH ROW EXECUTE FUNCTION public.document_learn_date_change();
CREATE TRIGGER document_learn_invoice_date AFTER UPDATE OF invoice_date ON public.invoices FOR EACH ROW EXECUTE FUNCTION public.document_learn_date_change();
CREATE TABLE public.document_read_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),uploaded_by uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('sales','invoice')),source_hash text NOT NULL,source_path text NOT NULL,source_name text NOT NULL,mime_type text NOT NULL,status text NOT NULL DEFAULT 'retained' CHECK(status IN ('retained','reading','needs_answer','posted','paused','failed')),error_message text,extraction jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,uploaded_by,kind,source_hash));
GRANT SELECT ON public.document_read_jobs TO authenticated;GRANT ALL ON public.document_read_jobs TO service_role;ALTER TABLE public.document_read_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY document_jobs_read ON public.document_read_jobs FOR SELECT TO authenticated USING(uploaded_by=auth.uid() AND public.user_has_tenant(auth.uid(),tenant_id));